contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // We take an arbitrary amount of Ether to forward to c.go. The test will call c.go{value: amount}()
    // and check that c.owner remains the same as before and that address(c).balance == 0 after the call.
    function run(uint256 amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount);

        // Read owner before
        address ownerBefore = c.owner(); if (__ESBMC_reverted()) return;

        // Call c.go forwarding `amount`. Capture whether it reverted.
        bool reverted;
        c.go{value: amount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // Read owner and contract balance after
        address ownerAfter = c.owner(); if (__ESBMC_reverted()) return;
        uint256 balAfter = address(c).balance;

        // General rule: owner never changes; c's balance is zero after the call; call may or may not revert
        assert(ownerAfter == ownerBefore && balAfter == 0);
    }

    // Accept any Ether sent back to this test contract
    receive() external payable {}
}

